// Java 生产者配置示例
Properties props = new Properties();
props.put("bootstrap.servers", "broker1:9092,broker2:9092");

// 场景1: 高吞吐 / 允许丢失（日志上报）
props.put("acks", "0");

// 场景2: 平衡吞吐与可靠性（旧系统兼容）
props.put("acks", "1");

// 场景3: 强可靠性（订单/支付，推荐生产配置）
props.put("acks", "all");                          // 等待所有 ISR 确认
props.put("enable.idempotence", "true");           // 幂等，重试安全
props.put("retries", String.valueOf(Integer.MAX_VALUE));
props.put("delivery.timeout.ms", "120000");        // 最长等待 2 分钟

// 幂等生产者的 ProducerBatch Header（简化）
// 每条消息携带 PID + Epoch + SequenceNumber
//
// 首次发送：PID=12345, Epoch=0, Seq=0  → Broker 接受，写入
// 网络超时重试：PID=12345, Epoch=0, Seq=0 → Broker 发现 Seq=0 已存在，返回 DuplicateSequence，不重复写入
// 下一条新消息：PID=12345, Epoch=0, Seq=1 → Broker 接受

Properties props = new Properties();
props.put("enable.idempotence", "true");   // 开启幂等（Kafka 3.0+ 默认 true）
// 幂等模式下以下参数自动约束：
// retries = Integer.MAX_VALUE（自动设置）
// acks = all（自动设置）
// max.in.flight.requests.per.connection <= 5
